"""Classify V46's sampled fitting waits using only its sealed audit."""

from collections import Counter, defaultdict
from datetime import datetime
import gzip
import hashlib
import json
from pathlib import Path


ROOT = Path("/home/longhao/experiment/.worktrees/beliefkv-v25-followup-20261011")
REPORTS = ROOT / "experiments/reports"
AUDIT = REPORTS / "v238_v46_final_wait_prefetch_20261013.json.gz"
QUALIFIED = REPORTS / "v241_v46_cutoff_qualification_20261013.json"
OUTPUT = REPORTS / "v242_v46_fitting_wait_gap_evidence_20261013.json"


def identity(row):
    source = {"join_wait": "join_ticket"}.get(row["source"], row["source"])
    return (
        source, row["workflow_id"], row["context_id"],
        None if source == "join_ticket" else row["context_epoch"],
        row.get("join_id") if source == "join_ticket" else None,
    )


def distribution(values):
    ordered = sorted(value for value in values if value is not None)
    if not ordered:
        return {"count": 0}

    def quantile(probability):
        position = probability * (len(ordered) - 1)
        lower = int(position)
        upper = min(lower + 1, len(ordered) - 1)
        return ordered[lower] + (ordered[upper] - ordered[lower]) * (position - lower)

    return {
        "count": len(ordered), "p50": quantile(.5), "p90": quantile(.9),
        "min": ordered[0], "max": ordered[-1],
    }


def main():
    if OUTPUT.exists():
        raise ValueError("preserve the existing gap receipt")
    audit_bytes, qualified_bytes = AUDIT.read_bytes(), QUALIFIED.read_bytes()
    audit = json.loads(gzip.decompress(audit_bytes))
    qualified = json.loads(qualified_bytes)
    if hashlib.sha256(audit_bytes).hexdigest() != qualified["sealed_report_sha256"]:
        raise ValueError("the audit differs from cutoff qualification")
    cutoff = qualified["administrative_cutoff_ts_ms"]
    actions = defaultdict(list)
    for action in audit["rows"]:
        if action["source"] in ("join_ticket", "join_wait", "tool_wait"):
            actions[identity(action)].append(action)

    details = []
    for wait in audit["wait_event_attribution"]["rows"]:
        completion = wait.get("completion_ts_ms")
        if (
            completion is None or completion > cutoff
            or (wait.get("max_pre_completion_fitting_full_bytes") or 0) <= 0
            or wait["early_started_and_reused_full_bytes"] > 0
        ):
            continue
        observed = [
            action for action in actions[identity(wait)]
            if action.get("submit_ts_ms") is not None
            and action["submit_ts_ms"] <= cutoff
        ]
        early = [
            action for action in observed if action["submit_ts_ms"] < completion
        ]
        early_full = [
            action for action in early if (action.get("pool_bytes") or {}).get("kv", 0) > 0
        ]
        category = (
            "no_observed_transfer_submission" if not observed
            else "submissions_only_at_or_after_completion" if not early
            else "early_submission_without_known_positive_full" if not early_full
            else "early_positive_full_without_next_request_reuse_proof"
        )
        known_service = wait.get("first_service_ts_ms")
        detail = {
            name: wait.get(name) for name in (
                "source", "workflow_id", "context_id", "context_epoch", "join_id",
                "completion_ts_ms", "next_request_id",
                "max_pre_completion_fitting_full_bytes",
                "first_positive_full_plan_relative_to_completion_ms",
                "pre_completion_plan_reasons", "pre_completion_blocked_details",
                "observed_planning_no_step_reasons", "observed_capacity_conditions",
                "remaining_native_full_host_hit_bytes", "demand_handoff_full_bytes_known",
            )
        }
        detail.update({
            "gap_evidence_category": category,
            "first_service_at_or_before_cutoff": (
                known_service is not None and known_service <= cutoff
            ),
            "post_cutoff_first_service_ts_ms": (
                known_service if known_service is not None and known_service > cutoff else None
            ),
            "early_submission_command_count": len(early),
            "early_full_command_count": len(early_full),
            "early_full_bytes_known": sum(action["pool_bytes"]["kv"] for action in early_full),
            "submitted_command_ids": [action["command_id"] for action in observed],
            "observed_early_full_reuse_values": {
                str(value): sum(
                    action["full_first_service_reused"] is value for action in early_full
                )
                for value in (True, False, None)
            },
            "recorded_residency_release_reasons": dict(Counter(
                event["reason"]
                for action in early_full for event in action.get("lease_events", ())
                if event["event"] == "prefetch_residency_released"
                and event["ts_ms"] <= cutoff
            )),
            "observed_native_reload_before_first_service_commands": sum(
                bool(action.get("native_reloads_before_first_service")) for action in early_full
            ),
        })
        details.append(detail)

    summary = {}
    for source in ("join_ticket", "tool_wait"):
        selected = [row for row in details if row["source"] == source]
        expected = qualified["event_counts"][source][
            "sampled_fitting_without_early_confirmed_reuse_events"
        ]
        if len(selected) != expected:
            raise ValueError(f"{source} gap denominator changed")
        categories = {}
        for category in sorted({row["gap_evidence_category"] for row in selected}):
            subset = [row for row in selected if row["gap_evidence_category"] == category]
            categories[category] = {
                "events": len(subset),
                "events_with_pre_completion_start_window": sum(
                    row["pre_completion_plan_reasons"].get("start_window", 0) > 0
                    for row in subset
                ),
                "first_service_at_or_before_cutoff_events": sum(
                    row["first_service_at_or_before_cutoff"] for row in subset
                ),
                "max_fitting_snapshot_full_bytes_sum": sum(
                    row["max_pre_completion_fitting_full_bytes"] for row in subset
                ),
                "remaining_native_full_host_hit_bytes_known": sum(
                    row["remaining_native_full_host_hit_bytes"] or 0 for row in subset
                ),
                "demand_handoff_full_bytes_known": sum(
                    row["demand_handoff_full_bytes_known"] or 0 for row in subset
                ),
                "early_full_bytes_known": sum(row["early_full_bytes_known"] for row in subset),
            }
        summary[source] = {
            "sampled_fitting_gap_events": len(selected),
            "categories": categories,
            "events_by_pre_completion_plan_reason": dict(Counter(
                reason for row in selected for reason in row["pre_completion_plan_reasons"]
            )),
            "events_by_pre_completion_blocked_detail": dict(Counter(
                reason for row in selected for reason in row["pre_completion_blocked_details"]
            )),
            "first_positive_full_plan_relative_to_completion_ms": distribution(
                row["first_positive_full_plan_relative_to_completion_ms"] for row in selected
            ),
        }
    helper_bytes = Path(__file__).read_bytes()
    report = {
        "schema_version": 1,
        "observed_at_local": datetime.now().astimezone().isoformat(),
        "collection_code_commit": audit["collection_code_commit"],
        "administrative_cutoff_ts_ms": cutoff,
        "inputs": {
            "audit": {"path": str(AUDIT), "sha256": hashlib.sha256(audit_bytes).hexdigest()},
            "cutoff": {
                "path": str(QUALIFIED), "sha256": hashlib.sha256(qualified_bytes).hexdigest(),
            },
        },
        "summary": summary, "rows": details,
        "helper_sha256": hashlib.sha256(helper_bytes).hexdigest(),
        "helper_utf8_source": helper_bytes.decode(),
        "semantics": (
            "Derived solely from sealed V238 and qualified V241; no raw reread. "
            "Categories partition the fitting-but-unproven gaps by observed submissions. "
            "A fitting snapshot is not capacity at the eventual trigger, a reservation "
            "or a proven counterfactual opportunity. Recorded reasons overlap and do not "
            "identify an exclusive cause. Byte totals of maximum fitting snapshots, "
            "early transfer, residual native Host hits and demand handoff are separate "
            "evidence, cannot be added into an oracle or throughput benefit. Unknown reuse "
            "is not waste. Outcomes after the administrative cutoff are censored."
        ),
    }
    OUTPUT.write_text(json.dumps(report, indent=2, allow_nan=False) + "\n")
    print(json.dumps(summary, indent=2))


if __name__ == "__main__":
    main()
